insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('juju-geo-t01','geografia','Controle biológico de pragas na agricultura','treino','O que é uma "praga" numa plantação?','["Um adubo que faz a planta crescer", "Insetos ou doenças que atacam e estragam as plantas", "Um tipo de semente", "A água da chuva"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t02','geografia','Controle biológico de pragas na agricultura','treino','No controle biológico de pragas, o agricultor usa:','["Inimigos naturais das pragas, como outros insetos", "Muito veneno químico", "Fogo na plantação", "Plástico em cima das plantas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t03','geografia','Controle biológico de pragas na agricultura','treino','Qual inseto ajuda o agricultor porque come os pulgões?','["A barata", "O mosquito da dengue", "A joaninha", "O cupim"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t04','geografia','Controle biológico de pragas na agricultura','treino','Uma vantagem do controle biológico é que ele:','["Deixa resíduos de veneno nos alimentos", "Polui os rios", "Mata todos os animais da plantação", "Não deixa veneno nos alimentos e não faz mal ao ambiente"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t05','geografia','Controle biológico de pragas na agricultura','treino','Usar menos agrotóxicos (venenos) na plantação ajuda a:','["Proteger a saúde das pessoas e a natureza", "Deixar a comida mais cara", "Aumentar as pragas", "Sujar os rios"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t06','geografia','Controle biológico de pragas na agricultura','treino','Cuidar do ambiente hoje, sem prejudicar as pessoas que vão viver no futuro, se chama:','["Desmatamento", "Sustentabilidade", "Poluição", "Enchente"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t07','geografia','Aquecimento global','treino','O efeito estufa natural é importante porque:','["Deixa a Terra gelada", "Faz chover todos os dias", "Mantém a Terra aquecida o suficiente para existir vida", "Apaga o Sol"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t08','geografia','Aquecimento global','treino','Qual gás é o principal causador do aumento do efeito estufa?','["Gás carbônico", "Gás de cozinha", "Oxigênio", "Gás hélio de balão"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t09','geografia','Aquecimento global','treino','O que aumenta a quantidade de gases que aquecem o planeta?','["Plantar árvores", "Andar de bicicleta", "Economizar energia", "Queimadas de florestas e fumaça de carros e fábricas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t10','geografia','Aquecimento global','treino','Uma consequência do aquecimento global é:','["O aumento do gelo nos polos", "O derretimento do gelo nos polos", "O fim da chuva para sempre", "A Terra ficar mais fria"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t11','geografia','Aquecimento global','treino','Se o gelo dos polos derrete, o nível do mar:','["Sobe e pode inundar áreas perto da praia", "Desce", "Não muda", "Fica congelado"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t12','geografia','Aquecimento global','treino','Qual atitude ajuda a diminuir o aquecimento global?','["Fazer queimadas", "Deixar luzes acesas sem ninguém", "Andar mais a pé ou de bicicleta e plantar árvores", "Usar o carro para ir até a esquina"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t13','geografia','Aquecimento global','treino','Aquecimento global é:','["O calor de um forno", "O aumento da temperatura de todo o planeta", "O verão de uma cidade só", "Uma febre"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t14','geografia','Os problemas ambientais na área urbana','treino','Antigamente, a maioria das pessoas morava no campo. Hoje, a maioria mora:','["Nas florestas", "Nas ilhas", "No mar", "Nas cidades"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t15','geografia','Os problemas ambientais na área urbana','treino','Por que a cidade costuma ser mais quente que o campo?','["Porque tem muito asfalto, concreto e poucas árvores", "Porque tem mais rios", "Porque o Sol só aparece na cidade", "Porque tem muitas plantações"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t16','geografia','Os problemas ambientais na área urbana','treino','O asfalto das ruas atrapalha porque:','["Deixa as ruas coloridas", "Faz as plantas crescerem", "Impede a água da chuva de entrar no solo", "Deixa o ar mais limpo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t17','geografia','Os problemas ambientais na área urbana','treino','A fumaça que sai dos escapamentos dos carros e das chaminés das fábricas causa:','["Poluição do ar", "Poluição sonora", "Ilha de gelo", "Chuva de doces"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t18','geografia','Os problemas ambientais na área urbana','treino','Na inversão térmica, a poluição fica presa perto do chão e pode causar:','["Mais vontade de comer", "Ardência nos olhos e problemas na garganta", "Mais sono", "Cabelo mais bonito"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t19','geografia','Os problemas ambientais na área urbana','treino','Lixo jogado na rua pode:','["Deixar a cidade mais limpa", "Atrair ratos e insetos que transmitem doenças", "Fazer as plantas crescerem", "Diminuir as enchentes"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t20','geografia','Os problemas ambientais na área urbana','treino','Comprar só o necessário ajuda o meio ambiente porque:','["Gera menos lixo, como embalagens", "Deixa a casa vazia", "Aumenta a poluição", "Gasta mais água"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t21','geografia','Os problemas ambientais na área urbana','treino','Buzinas, obras e som muito alto causam:','["Poluição da água", "Poluição sonora", "Ilha de calor", "Inversão térmica"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t22','geografia','Os problemas ambientais na área urbana','treino','Uma avenida cheia de placas, cartazes e telas luminosas tem:','["Poluição do solo", "Poluição visual", "Poluição da água", "Nenhuma poluição"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t23','geografia','Poluição dos rios','treino','Como os agrotóxicos usados na plantação podem chegar ao rio?','["Pelo vento que sopra para o céu", "Os peixes levam para o rio", "A água da chuva leva o veneno até o rio", "Eles não chegam nunca ao rio"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t24','geografia','Poluição dos rios','treino','Peixes mortos boiando no rio são um sinal de que:','["A água está limpa", "O rio está poluído", "Choveu muito", "Os peixes estão dormindo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t25','geografia','Poluição dos rios','treino','Qual destes polui os rios nas cidades?','["Árvores na margem", "Peixes nadando", "Pássaros bebendo água", "Esgoto das casas e lixo jogado na água"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t26','geografia','Poluição dos rios','treino','Quanto da água do planeta é doce, aquela que podemos usar?','["Quase toda", "Metade", "Uma parte muito pequena", "Nenhuma"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t27','geografia','Poluição dos rios','treino','Assoreamento é quando:','["O rio fica cheio de terra, areia e lixo no fundo e fica mais raso", "O rio fica mais fundo", "O rio vira mar", "O rio congela"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t28','geografia','Poluição dos rios','treino','Um rio poluído e cheio de lixo pode causar:','["Mais peixes", "Água mais limpa", "Enchentes e doenças", "Mais árvores"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-t29','geografia','Poluição dos rios','treino','Qual atitude ajuda a proteger os rios?','["Jogar o lixo no lixo, nunca no rio", "Jogar óleo de cozinha na pia", "Jogar garrafas no rio", "Cortar as árvores da margem"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p01','geografia','Controle biológico de pragas na agricultura','prova','Um agricultor tem pulgões na horta e não quer usar veneno. O que ele pode fazer?','["Jogar mais agrotóxico", "Colocar fogo na horta", "Soltar joaninhas, que comem os pulgões", "Arrancar todas as plantas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p02','geografia','Controle biológico de pragas na agricultura','prova','Por que o controle biológico é bom para quem come os alimentos?','["Porque os alimentos ficam sem resíduos de veneno", "Porque os alimentos ficam maiores", "Porque os alimentos ficam mais doces", "Porque deixa a comida mais barata sempre"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p03','geografia','Controle biológico de pragas na agricultura','prova','Qual destes é um exemplo de sustentabilidade?','["Desmatar para plantar mais", "Jogar lixo no rio", "Usar muito veneno na plantação", "Usar inimigos naturais e menos veneno na plantação"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p04','geografia','Aquecimento global','prova','Por que se diz que o problema não é o efeito estufa, mas o seu aumento?','["Porque o efeito estufa é natural e necessário, mas gases em excesso aquecem demais a Terra", "Porque o efeito estufa não existe", "Porque o efeito estufa esfria a Terra", "Porque só existe efeito estufa nas plantas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p05','geografia','Aquecimento global','prova','Qual é a ordem certa?','["Gelo derrete → mais poluição → mar desce", "Mais gases poluentes → Terra mais quente → gelo dos polos derrete", "Terra mais fria → mais gelo → mar sobe", "Plantar árvores → mais calor → mais gelo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p06','geografia','Aquecimento global','prova','Qual atitude NÃO ajuda a combater o aquecimento global?','["Plantar árvores", "Apagar luzes que não estão sendo usadas", "Fazer queimadas nas matas", "Usar mais transporte coletivo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p07','geografia','Os problemas ambientais na área urbana','prova','Numa cidade com muitos prédios e asfalto e quase nenhuma árvore, a temperatura costuma ser:','["Mais alta do que em áreas com muita vegetação", "Igual à de uma floresta", "Mais baixa do que no campo", "Sempre abaixo de zero"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p08','geografia','Os problemas ambientais na área urbana','prova','Qual problema ambiental está ligado ao excesso de embalagens descartadas?','["Poluição sonora", "Ilha de calor", "Inversão térmica", "Acúmulo de lixo"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p09','geografia','Os problemas ambientais na área urbana','prova','Qual atitude ajuda a melhorar o ambiente da cidade?','["Plantar árvores e cuidar das praças", "Asfaltar todos os parques", "Buzinar sem parar", "Jogar lixo nas calçadas"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p10','geografia','Poluição dos rios','prova','Leia: "A chuva carregou o veneno da plantação para o rio, e as crianças que tomaram banho nele ficaram doentes." O que causou o problema?','["O sol forte", "Os peixes do rio", "O excesso de agrotóxicos na plantação", "As árvores da margem"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p11','geografia','Poluição dos rios','prova','Por que precisamos economizar água doce?','["Porque ela é muito salgada", "Porque é só uma pequena parte da água do planeta", "Porque ela nunca acaba", "Porque não serve para beber"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd'),
  ('juju-geo-p12','geografia','Poluição dos rios','prova','Um rio cheio de lixo e terra no fundo transborda com facilidade. Esse problema se chama:','["Ilha de calor", "Inversão térmica", "Efeito estufa", "Assoreamento"]'::jsonb,'014341f0-99f3-4e14-b21d-6b4efc9bafbd');
insert into gabarito (questao_id,correta,explicacao) values
  ('juju-geo-t01',1,'Pragas são insetos e doenças que prejudicam a plantação.'),
  ('juju-geo-t02',0,'O controle biológico usa a própria natureza: animais e seres vivos que comem ou combatem as pragas.'),
  ('juju-geo-t03',2,'A joaninha é predadora natural dos pulgões que atacam as plantas.'),
  ('juju-geo-t04',3,'Os inimigos naturais não deixam resíduos nos alimentos e não fazem mal às pessoas nem ao ambiente.'),
  ('juju-geo-t05',0,'Menos veneno significa alimentos mais saudáveis e menos poluição na água e no solo.'),
  ('juju-geo-t06',1,'Sustentabilidade é usar a natureza de um jeito que ela continue existindo para as próximas gerações.'),
  ('juju-geo-t07',2,'Alguns gases seguram parte do calor do Sol. Sem isso, a Terra seria fria demais para a vida.'),
  ('juju-geo-t08',0,'O gás carbônico, em excesso, segura calor demais e aquece o planeta.'),
  ('juju-geo-t09',3,'Queimadas, carros e fábricas que queimam combustível soltam muitos gases poluentes no ar.'),
  ('juju-geo-t10',1,'Com o planeta mais quente, o gelo das calotas polares derrete.'),
  ('juju-geo-t11',0,'A água do gelo derretido vai para o oceano, o mar sobe e pode alagar cidades no litoral.'),
  ('juju-geo-t12',2,'Menos carros e mais árvores significam menos gás carbônico no ar.'),
  ('juju-geo-t13',1,'É o aumento da temperatura média da Terra causado pelo excesso de gases poluentes.'),
  ('juju-geo-t14',3,'Com as indústrias e o comércio, muita gente foi morar nas cidades (áreas urbanas).'),
  ('juju-geo-t15',0,'Asfalto e prédios esquentam rápido, e há pouca vegetação. Isso forma a "ilha de calor".'),
  ('juju-geo-t16',2,'A água não infiltra no asfalto e escorre pelas ruas, o que ajuda a causar enchentes.'),
  ('juju-geo-t17',0,'Os gases da fumaça sujam o ar que respiramos: é a poluição atmosférica.'),
  ('juju-geo-t18',1,'Com o ar frio preso embaixo, a poluição não sobe e as pessoas respiram esse ar sujo.'),
  ('juju-geo-t19',1,'O lixo acumulado tem mau cheiro e atrai ratos e insetos que espalham doenças.'),
  ('juju-geo-t20',0,'Quanto mais compramos, mais embalagens viram lixo. Consumir com consciência diminui o lixo.'),
  ('juju-geo-t21',1,'Barulho em excesso é poluição sonora e prejudica a saúde e o sossego.'),
  ('juju-geo-t22',1,'Excesso de informação para os olhos é poluição visual.'),
  ('juju-geo-t23',2,'A chuva escorre pela plantação e carrega o veneno até os rios.'),
  ('juju-geo-t24',1,'Quando a água fica poluída, os peixes podem morrer.'),
  ('juju-geo-t25',3,'Esgoto, lixo e restos das indústrias jogados no rio deixam a água poluída.'),
  ('juju-geo-t26',2,'A maior parte da água da Terra é salgada (do mar). A água doce é pouquinha, por isso precisamos economizar.'),
  ('juju-geo-t27',0,'Terra, areia e lixo se acumulam no fundo do rio. Ele fica raso e transborda mais fácil, causando enchentes.'),
  ('juju-geo-t28',2,'Lixo entope os rios e as galerias, a água transborda e a água suja espalha doenças.'),
  ('juju-geo-t29',0,'Lixo no lugar certo não vai parar nos rios. Árvores na margem também protegem o rio.'),
  ('juju-geo-p01',2,'As joaninhas são inimigas naturais dos pulgões. Isso é controle biológico.'),
  ('juju-geo-p02',0,'Sem veneno químico, os alimentos chegam mais saudáveis à nossa mesa.'),
  ('juju-geo-p03',3,'Cuidar da plantação sem estragar a natureza é uma prática sustentável.'),
  ('juju-geo-p04',0,'Um pouco de efeito estufa mantém a vida. O excesso de gases, por causa da poluição, aquece demais o planeta.'),
  ('juju-geo-p05',1,'A poluição aumenta os gases, a Terra esquenta e o gelo dos polos derrete, fazendo o mar subir.'),
  ('juju-geo-p06',2,'Queimadas soltam muito gás carbônico e pioram o aquecimento global.'),
  ('juju-geo-p07',0,'É a ilha de calor: concreto e asfalto esquentam, e falta vegetação para refrescar.'),
  ('juju-geo-p08',3,'Embalagens jogadas fora sem cuidado aumentam muito o lixo das cidades.'),
  ('juju-geo-p09',0,'Árvores refrescam, ajudam a água da chuva a entrar no solo e deixam o ar melhor.'),
  ('juju-geo-p10',2,'O veneno usado em excesso foi levado pela chuva e contaminou a água do rio.'),
  ('juju-geo-p11',1,'Quase toda a água da Terra é salgada. A água doce que podemos usar é pouca.'),
  ('juju-geo-p12',3,'O assoreamento deixa o rio raso. Com a chuva, ele transborda e causa enchentes.');
